import { FilesService, sniff } from './files.module';
import { Membership } from '@prisma/client';
import { NotFoundException } from '@nestjs/common';
describe('private file boundary',()=>{
 it('sniffs only accepted signatures',()=>{
  expect(sniff(Buffer.from('%PDF-1.7'))).toBe('application/pdf');
  expect(sniff(Buffer.from('<script>'))).toBeNull();
 });
 it('does not expose other employee documents to finance',async()=>{
  const db={storedFile:{findUnique:jest.fn().mockResolvedValue({id:'file',employeeId:'other',category:'EMPLOYEE_DOCUMENT',archived:false})}};
  const m={companyId:'company',employeeId:'self',roles:['FINANCE']} as Membership;
  await expect(new FilesService(db as never,{} as never,{} as never).authorized(m,'file')).rejects.toBeInstanceOf(NotFoundException);
  expect(db.storedFile.findUnique).toHaveBeenCalledWith({where:{companyId_id:{companyId:'company',id:'file'}}});
 });
 it('allows finance to read linked claim receipts only',async()=>{
  const db={storedFile:{findUnique:jest.fn().mockResolvedValue({id:'file',employeeId:'other',category:'CLAIM_RECEIPT',claimId:'claim'})},claim:{findUnique:jest.fn().mockResolvedValue({id:'claim'})}};
  await expect(new FilesService(db as never,{} as never,{} as never).authorized({companyId:'company',roles:['FINANCE']} as Membership,'file')).resolves.toMatchObject({id:'file'});
 });
});

